fun episodeKind(job: PodcastJob): String = if (job.meta != null || scriptureTitle.containsMatchIn(job.title.trim().removePrefix("Bible - "))) "Bible lesson"
    else if (job.sites.isNotEmpty() || job.stories.isNotEmpty()) "Daily briefing" else podcastStyles[job.style] ?: "Podcast"
